# /audit: single AUDIT.md assembled from the sections of the lens sets, and the
# idempotent resume of the previous deliverables.
#
# The engine of audit.py runs once per active lens set (legacy, vibecode,
# research); this module adds what is specific to the unified audit.
#
# - SO-01: one deliverable, <REPO>/AUDIT.md: header ("Generated by /audit on
#   <date>", profiles, lenses, complete or sampled, "Imported from"), then the
#   section block of every active set in the order of the stamp, then a single
#   "Next". Relative links in "/". Texts: templates/audit/unified.json.
# - SO-04: FD-11 is applied to AUDIT.md before it is written.
# - SO-05: ROADMAP-legacy.md, AUDIT-vibecode.md and AUDIT-lab.md are never
#   written.
# - MG-01: AUDIT.md is read when it exists; every previous deliverable present
#   whose sha256 is not already recorded in AUDIT.md is read too (AU-09).
# - MG-02: an import is recorded as `<!-- harness:import <file> sha256=<hash> -->`
#   followed by the visible line "Imported from: <file>". A file already
#   imported whose hash changed is not re-imported: warning, AUDIT.md wins. A
#   previous file never imported is imported even when AUDIT.md exists.
# - MG-03: statuses (FAIT, EN_COURS, TRANCHEE) are preserved by the resume of
#   the engine; numbering goes on beyond the highest imported id (AU-08).
# - MG-04: the previous deliverables are never modified nor deleted.
# - MG-05: same inputs and same date -> byte-identical AUDIT.md, no new import.

from __future__ import annotations

import hashlib
import json
import re
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple

from . import audit, findings, registry, runs

DELIVERABLE = "AUDIT.md"
TEMPLATE = Path(__file__).resolve().parent.parent / "templates" / "audit" / "unified.json"
IMPORT_RE = re.compile(r"^<!-- harness:import (?P<file>\S+) sha256=(?P<hash>[0-9a-f]{64}) -->$", re.M)
SET_START = "<!-- harness:set %s -->"
SET_END = "<!-- harness:set-end %s -->"
# The "next" section and the "run" line of a set render (English templates, then the French legacy ones).
NEXT_HEADINGS = ("## Next", "## Suite")
LAUNCH_MARKERS = ("**Run**", "**Lancer**")


def texts() -> Dict[str, Any]:
    return json.loads(TEMPLATE.read_text(encoding="utf-8"))


def sha256_of(path: Path) -> str:
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def recorded_imports(text: str) -> Dict[str, str]:
    return {m.group("file"): m.group("hash") for m in IMPORT_RE.finditer(text or "")}


def slice_of(text: str, skill: str) -> Optional[str]:
    """The block of one lens set inside AUDIT.md, or None."""
    start, end = SET_START % skill, SET_END % skill
    a = text.find(start)
    if a == -1:
        return None
    b = text.find(end, a)
    if b == -1:
        raise audit.AuditStop("%s: set block %s is not closed" % (DELIVERABLE, skill))
    return text[a + len(start):b].strip("\n") + "\n"


def _merge(first: Dict[str, Any], second: Dict[str, Any]) -> Dict[str, Any]:
    """Two parsed deliverables of one skill: the first one wins on a shared id."""
    ids = {e["id"] for e in first["entries"]}
    entries = first["entries"] + [e for e in second["entries"] if e["id"] not in ids]
    numbering = dict(second["numbering"])
    for prefix, number in first["numbering"].items():
        numbering[prefix] = max(number, numbering.get(prefix, 0))
    tables = dict(second["tables"])
    tables.update(first["tables"])
    headings = dict(second["headings"])
    headings.update(first["headings"])
    return {"skill": first["skill"], "entries": entries, "numbering": numbering, "headings": headings,
            "tables": tables}


def resume(repo: Path, skill: str) -> Dict[str, Any]:
    """MG-01 to MG-03: {"parsed": resume document or None, "imports": [...], "warnings": [...]}."""
    repo = Path(repo)
    p = audit.profile(skill)
    unified = repo / DELIVERABLE
    unified_text = unified.read_text(encoding="utf-8") if unified.is_file() else ""
    recorded = recorded_imports(unified_text)
    parsed: Optional[Dict[str, Any]] = None
    block = slice_of(unified_text, skill) if unified_text else None
    if block is not None:
        parsed = audit.parse_deliverable(skill, block)
    imports: List[Dict[str, str]] = []
    warnings: List[str] = []
    old = repo / p.deliverable
    if old.is_file():
        digest = sha256_of(old)
        if p.deliverable in recorded:
            if recorded[p.deliverable] != digest:
                warnings.append("%s changed since its import into %s: not re-imported, %s wins"
                                % (p.deliverable, DELIVERABLE, DELIVERABLE))
        else:
            previous = audit.parse_deliverable(skill, old.read_text(encoding="utf-8"))
            parsed = previous if parsed is None else _merge(parsed, previous)
            imports.append({"file": p.deliverable, "sha256": digest})
    return {"parsed": parsed, "imports": imports, "warnings": warnings, "recorded": recorded}


def strip_set_block(skill: str, text: str) -> str:
    """Section block of a set render: its head and its own "Suite" are replaced
    by the unified ones."""
    head = len(audit.texts()[skill]["head"])
    lines = text.splitlines()[head:]
    cut = next((lines.index(h) for h in NEXT_HEADINGS if h in lines), None)
    if cut is not None:
        lines = lines[:cut]
    launch = texts()["launch"]
    lines = [l.replace(launch["from"], launch["to"]) if any(m in l for m in LAUNCH_MARKERS) else l
             for l in lines]   # SO-03
    while lines and not lines[-1].strip():
        lines.pop()
    while lines and not lines[0].strip():
        lines.pop(0)
    return "\n".join(lines) + "\n"


def cycle_peers(repo: Path, run: Path) -> Dict[str, str]:
    """AD-07: RG-02 key -> "<id> (<set>)" of the findings already reported by the
    other lens sets of the current /audit cycle (the unified runs started since
    the last `audit open`, this run excepted). Without an open run: none."""
    directory = Path(repo) / runs.RUNS_DIR
    opens = sorted(p.name for p in directory.glob("audit-*.state.json")) if directory.is_dir() else []
    if not opens:
        return {}
    since = opens[-1][len("audit-"):][:len("00000000-000000")]
    own = Path(run).name[:-len(".jsonl")] if str(run).endswith(".jsonl") else Path(run).name
    peers: Dict[str, str] = {}
    for path in sorted(directory.glob("*.state.json")):
        base = path.name[:-len(".state.json")]
        if base == own or base.startswith("audit-"):
            continue
        stamp = base.rsplit("-", 2)
        if len(stamp) != 3 or stamp[1] + "-" + stamp[2] < since:
            continue
        state = json.loads(path.read_text(encoding="utf-8"))
        if not state.get("unified") or not state.get("audit_skill"):
            continue
        for fid, f in state.get("findings", {}).items():
            if f.get("status") != findings.DUPLICATE:
                peers.setdefault(registry.project_key(f), "%s (%s)" % (fid, state["audit_skill"]))
    return peers


def assemble(repo: Path, blocks: Sequence[Tuple[str, str]], date: str, profile_names: Sequence[str],
             lens_names: Sequence[str], sampled: bool, imports: Iterable[Dict[str, str]]) -> Dict[str, Any]:
    """SO-01, SO-04, MG-02, MG-05: writes AUDIT.md. `blocks`: (skill, section text) in the order of the stamp."""
    repo = Path(repo)
    t = texts()
    dest = repo / DELIVERABLE
    before = dest.read_text(encoding="utf-8") if dest.is_file() else ""
    # An imported file stays recorded (its sha256 is the proof that it was read).
    known = recorded_imports(before)
    for item in imports:
        known.setdefault(item["file"], item["sha256"])
    # A set block of a previous run that this run did not audit is kept as it is.
    done = {skill for skill, _ in blocks}
    kept: List[Tuple[str, str]] = []
    for line_skill in audit.PROFILES:
        if line_skill not in done and before:
            old_block = slice_of(before, line_skill)
            if old_block is not None:
                kept.append((line_skill, old_block))
    order = {s: i for i, s in enumerate(audit.PROFILES)}
    all_blocks = sorted(list(blocks) + kept, key=lambda b: order[b[0]]) if kept else list(blocks)
    lines: List[str] = []
    lines += [x.replace("$date", date).replace("$profiles", ", ".join(profile_names))
              .replace("$lenses", ", ".join(lens_names))
              .replace("$coverage", t["coverage"]["sampled" if sampled else "complete"]) for x in t["head"]]
    for file in sorted(known):
        lines.append("<!-- harness:import %s sha256=%s -->" % (file, known[file]))
        lines.append(t["imported"].replace("$file", file))
    for skill, text in all_blocks:
        lines += ["", SET_START % skill, text.rstrip("\n"), SET_END % skill]
    lines.append("")
    lines += t["next"]
    text = "\n".join(lines) + "\n"
    hits = findings.check_forbidden(text)
    if hits:
        raise audit.AuditStop("forbidden string in %s, line %d: %s: nothing written"
                              % (DELIVERABLE, hits[0]["line"], hits[0]["text"]))
    if text != before:
        with open(str(dest), "w", encoding="utf-8", newline="\n") as fh:
            fh.write(text)
    return {"file": DELIVERABLE, "state": "créé" if not before else "identique" if text == before else "fusionné",
            "imports": sorted(known)}
